767		// The final list reflects only the committed changes.
768		if len(got.Services) != 1 || got.Services[0].Revision != 2 {
769			t.Fatalf("services: %+v", got.Services)
770		}
771		insts := got.Services[0].Instances
772		if len(insts) != 2 {
773			t.Fatalf("instances: %+v", insts)
774		}
