776			t.Fatalf("a should be healthy at its new address: %+v", insts[0])
777		}
778		if insts[1].ID != "b" || insts[1].Address != "h2:2" || insts[1].Health != "healthy" || insts[1].Sequence != 22 || insts[1].Reason != "" {
779			t.Fatalf("b should be healthy again: %+v", insts[1])
780		}
