1241			t.Fatalf("result 16: %+v", r)
1242		}
1243		// 17: the cursor survived the empty list on b, so the rotation continues
1244		// just after b and returns c with its current address and new sequence.
1245		if r := got.Results[17]; !r.OK || r.InstanceID != "c" || r.Address != "h3:3" || r.Sequence != 1 || r.Revision != 3 {
1246			t.Fatalf("result 17 should resume after b at c: %+v", r)
1247		}
1248		// 18: only now does the rotation wrap back to a.
1249		if r := got.Results[18]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 1 || r.Revision != 3 {
1250			t.Fatalf("result 18 should wrap to a: %+v", r)
1251		}
