1278	// TestRejectedConflictReplacementKeepsRotationPosition isolates the rotation
1279	// guarantee at the batch level: the conflicting replacement is the very next
1280	// item after the first successful selection, so the following select must
1281	// continue at the next healthy id (i2). A failure path that reset the rotation
1282	// would select i1 again instead. The conflicting list is otherwise valid and
1283	// changes i1's address, which also must not take effect.
1284	func TestRejectedConflictReplacementKeepsRotationPosition(t *testing.T) {
